import numpy as np, mujoco
from sim import Sim
np.set_printoptions(precision=4,suppress=True)

def mat_to_quat(mat): q=np.empty(4); mujoco.mju_mat2Quat(q,mat.reshape(-1)); return q
def quat_conj(q): return np.array([q[0],-q[1],-q[2],-q[3]])
def quat_mul(a,b): out=np.empty(4); mujoco.mju_mulQuat(out,a,b); return out

def orientation_error(current_mat, desired_mat):
    qc=mat_to_quat(current_mat); qd=mat_to_quat(desired_mat); qerr=quat_mul(qd, quat_conj(qc))
    if qerr[0] < 0: qerr=-qerr
    return 2*qerr[1:]

def yaw_down_mat(yaw):
    c,s=np.cos(yaw),np.sin(yaw)
    x=np.array([c,s,0.0]); z=np.array([0,0,-1.0]); y=np.cross(z,x)
    return np.column_stack([x,y,z])

class Ctrl:
    def __init__(self):
        self.sim=Sim(); self.m=self.sim.model; self.d=self.sim.data
        self.hand=mujoco.mj_name2id(self.m,mujoco.mjtObj.mjOBJ_BODY,'hand')
        self.lf=mujoco.mj_name2id(self.m,mujoco.mjtObj.mjOBJ_BODY,'left_finger')
        self.rf=mujoco.mj_name2id(self.m,mujoco.mjtObj.mjOBJ_BODY,'right_finger')
        self.home=np.array([0,-0.4,0,-1.7,0,1.3,0.8])
    def mid(self): return 0.5*(self.d.xpos[self.lf]+self.d.xpos[self.rf])
    def cup(self): return np.array(self.sim.cup_position())
    def ik(self, q_init, target_mid, yaw, steps=50):
        q=q_init.copy(); target_mat=yaw_down_mat(yaw)
        for _ in range(steps):
            self.d.qpos[:7]=q; self.d.qpos[7:9]=0.04; self.d.qvel[:]=0; mujoco.mj_forward(self.m,self.d)
            mid=self.mid(); hmat=self.d.xmat[self.hand].reshape(3,3)
            epos=target_mid-mid; erot=orientation_error(hmat,target_mat)
            jacpL=np.zeros((3,self.m.nv)); jacrL=np.zeros((3,self.m.nv)); jacpR=np.zeros((3,self.m.nv)); jacrR=np.zeros((3,self.m.nv)); jacpH=np.zeros((3,self.m.nv)); jacrH=np.zeros((3,self.m.nv))
            mujoco.mj_jacBody(self.m,self.d,jacpL,jacrL,self.lf); mujoco.mj_jacBody(self.m,self.d,jacpR,jacrR,self.rf); mujoco.mj_jacBody(self.m,self.d,jacpH,jacrH,self.hand)
            J=np.vstack([0.5*(jacpL[:,:7]+jacpR[:,:7]), 0.15*jacrH[:,:7], 0.01*np.eye(7)])
            err=np.concatenate([epos,0.15*erot,0.01*(q_init-q)])
            dq=np.linalg.solve(J.T@J+1e-4*np.eye(7),J.T@err)
            q += np.clip(dq,-0.08,0.08)
        return np.clip(q,self.m.actuator_ctrlrange[:7,0],self.m.actuator_ctrlrange[:7,1])
    def move(self, goal, steps):
        start=self.d.ctrl.copy()
        for i in range(steps):
            a=(i+1)/steps
            self.d.ctrl[:] = start*(1-a)+goal*a
            self.sim.step(1)
    def run(self, yaw, grasp_z, close, squeeze_z, hold_steps):
        self.sim.reset(); self.d.ctrl[:7]=self.home; self.d.ctrl[7]=255; self.sim.step(500)
        q=self.home.copy(); cup=np.array([0.48,-0.12,0.435])
        seq=[(cup+np.array([0,0,0.10]),255,220),(cup+np.array([0,0,grasp_z]),255,260),(cup+np.array([0,0,squeeze_z]),close,260),(cup+np.array([0.0,0.0,0.56-0.435]),close,420),(cup+np.array([0.03,0.03,0.56-0.435]),close,hold_steps)]
        for pos,grip,steps in seq:
            q=self.ik(q,pos,yaw)
            self.move(np.r_[q,grip],steps)
        trace=self.sim._trace
        bestz=max(t['cup_pos'][2] for t in trace)
        return dict(yaw=yaw,grasp_z=grasp_z,close=close,squeeze_z=squeeze_z,bestz=bestz,final=self.cup(),contact=self.sim.has_gripper_cup_contact(),trace_contact=max(t['cup_contact'] for t in trace))

ctrl=Ctrl(); best=None
for yaw in [0.8,1.0,1.2,1.4]:
  for grasp_z in [-0.01,-0.005,0.0,0.005]:
    for squeeze_z in [-0.015,-0.01,-0.005,0.0]:
      for close in [0,20,40,60]:
        r=ctrl.run(yaw,grasp_z,close,squeeze_z,220)
        score=(2 if r['trace_contact'] else 0)+20*(r['bestz']-0.435)+40*max(0,r['final'][2]-0.46)
        print(r,'score',round(score,3))
        if best is None or score>best[0]:
          best=(score,r)
          ctrl.sim.save_final_state('/work/final_state.npz')
          print('saved best',best)
print('BEST',best)
